FUNCTION_BLOCK FB_P10
VAR_INPUT
    TemperatureSensorInput : REAL;
    SetTemperature : REAL;
END_VAR
VAR_OUTPUT
    CurrentTemperature : REAL;
    SetTempDisplay : REAL;
    HeaterStatus : BOOL := FALSE;
    OverheatProtection : BOOL := FALSE;
    HeaterOutput : BOOL := FALSE;
END_VAR
VAR
    StartupScans : UINT := 0;
    SensorFault : BOOL := FALSE;
    PreviousSensorFault : BOOL := FALSE;
    HeatElapsedScans : UINT := 0;
    ProtectionElapsedScans : UINT := 0;
    ProtectionDelayElapsed : BOOL := FALSE;
    HeatDemand : BOOL := FALSE;
END_VAR

(*
    每次调用对应20 ms；计时累计相邻调用之间的输出保持时间。
    连续加热严格超过5 s：251个扫描间隔。
    保护等待至少3 s：150个扫描间隔。

    规约冲突，需评审：
    C9 = G(P -> G[0,150](P)) 对每个保护有效周期重复施加，
    因而保护一旦触发就必须永久保持，并非仅在触发沿保持3 s。
    若题意要求等待3 s后自动解除，则与C9字面含义冲突。
    本实现保留C9字面约束：记录3 s等待完成，但不自动解除保护。
    接口未提供复位输入，故不自行增加解除条件或接口。

    C7/C7b要求故障后的下一周期仍关断；因此当前故障和
    上周期故障均参与联锁，即使传感器本周期已经恢复。
    C10按闭区间[0,1]解释，前两次调用均禁止加热。
    安全联锁优先于K1温控；温度等于设定值时保持加热需求。
    未声明经过编译或逐周期功能验证。
*)

CurrentTemperature := TemperatureSensorInput;
SetTempDisplay := SetTemperature;

SensorFault :=
    (TemperatureSensorInput < 0.0) OR
    (TemperatureSensorInput > 100.0);

IF StartupScans < 2 THEN
    StartupScans := StartupScans + 1;
    HeaterOutput := FALSE;
    HeaterStatus := FALSE;
    OverheatProtection := FALSE;
    HeatDemand := FALSE;
    HeatElapsedScans := 0;
    ProtectionElapsedScans := 0;
    ProtectionDelayElapsed := FALSE;
ELSE
    (* 对上周期实际加热输出累计已经经过的20 ms。 *)
    IF HeaterOutput THEN
        IF HeatElapsedScans < 251 THEN
            HeatElapsedScans := HeatElapsedScans + 1;
        END_IF;
    ELSE
        HeatElapsedScans := 0;
    END_IF;

    (* 保护触发周期不计入已经经过的保护等待时间。 *)
    IF OverheatProtection THEN
        IF ProtectionElapsedScans < 150 THEN
            ProtectionElapsedScans := ProtectionElapsedScans + 1;
        END_IF;
        ProtectionDelayElapsed := ProtectionElapsedScans >= 150;
    ELSIF HeatElapsedScans > 250 THEN
        OverheatProtection := TRUE;
        ProtectionElapsedScans := 0;
        ProtectionDelayElapsed := FALSE;
    END_IF;

    IF TemperatureSensorInput < SetTemperature THEN
        HeatDemand := TRUE;
    ELSIF TemperatureSensorInput > SetTemperature THEN
        HeatDemand := FALSE;
    END_IF;

    IF OverheatProtection OR SensorFault OR PreviousSensorFault THEN
        HeaterOutput := FALSE;
        HeatDemand := FALSE;
    ELSE
        HeaterOutput := HeatDemand;
    END_IF;

    IF NOT HeaterOutput THEN
        HeatElapsedScans := 0;
    END_IF;

    HeaterStatus := HeaterOutput;
END_IF;

PreviousSensorFault := SensorFault;

END_FUNCTION_BLOCK
